// Üretilen dosya: tool/ozgun/uret.py. İstatistik ve Veri Bilimi · Bayes çıkarımı, tanı testleri (duyarlılık, özgüllük, temel oran yanılgısı), karar ağaçları ve beklenen değer hesapları (kolay).
const ozStatistics15Kolay = <(String, String, List<String>, String)>[
  ('Bayesçi istatistikte herhangi bir deneysel veri veya gözlem elde edilmeden önce bir hipoteze atanan başlangıç inanç derecesine ne ad verilir?', 'Önsel olasılık', ['Sonsal olasılık', 'Marjinal olabilirlik', 'Koşulsuz varyans'], 'Gözlem öncesindeki mevcut bilgi veya uzman kanaatine dayanan başlangıç olasılığı önsel (prior) olasılık olarak adlandırılır.'),
  ('Yeni bir kanıt gözlemlendikten sonra Bayes teoremi yardımıyla güncellenmiş olan hipotez olasılığı hangi kavramla ifade edilir?', 'Sonsal olasılık', ['Önsel olasılık', 'Bileşik olabilirlik', 'Örneklem standart hatası'], 'Kanıtın ışığında önsel inancın güncellenmesiyle ulaşılan koşullu olasılık P(H|V), sonsal (posterior) olasılıktır.'),
  ('Bir hipotezin doğru olduğu varsayıldığında eldeki verinin gözlemlenme olasılığını ölçen P(Veri | Hipotez) terimine Bayes çıkarımında ne denir?', 'Olabilirlik', ['Normalleştirme sabiti', 'Önsel dağılım yoğunluğu', 'Kümülatif hata payı'], 'Hipotez sabit tutulup verinin o hipotez altında ne kadar olası olduğunu gösteren P(V|H) terimi olabilirlik fonksiyonudur.'),
  ('Bir dedektif iki şüpheliden A ve B\'ye başlangıçta eşit şüpheyle (1:1 bahis oranıyla) yaklaşmaktadır. Olay yerindeki ayak izinin A\'dan çıkma olasılığı %40, B\'den çıkma olasılığı %10 ise kanıt sonrası A\'nın B\'ye karşı sonsal bahis oranı kaç olur?', '4:1', ['2:1', '3:1', '8:1'], 'Önsel oran 1:1 iken olabilirlik oranı 0,40 / 0,10 = 4 olduğundan sonsal bahis oranı doğrudan 4:1 değerine yükselir.'),
  ('Parametre uzayında hiçbir değere özel bir üstünlük tanımayan, bilgi eksikliğini yansıtmak amacıyla tüm olası durumlara eşit ağırlık atayan önsel dağılım türü hangisidir?', 'Bilgilendirici olmayan (tekdüze/düz) önsel', ['Aşırı yoğunlaşmış Dirac önseli', 'Asimetrik kuyruklu sonsal dağılım', 'Kısıtlanmış ampirik varyans önseli'], 'Laplace\'ın yetersiz neden ilkesine paralel biçimde tüm durumlara eşit yoğunluk atayan önsellere bilgilendirici olmayan (flat/non-informative) önsel denir.'),
  ('Bir arkeolog bulduğu seramik parçasının Tunç Çağı\'na ait olma önsel olasılığını %50, Demir Çağı\'na ait olma olasılığını %50 olarak alıyor. Parçadaki kobalt boyası izine Tunç Çağı eserlerinin %5\'inde, Demir Çağı eserlerinin %45\'inde rastlanıyor. Kobalt izi saptanan bu eserin Demir Çağı\'na ait olma olasılığı yüzde kaçtır?', '%90', ['%85', '%75', '%95'], 'Önseller eşit olduğundan sonsal olasılık doğrudan olabilirliklerin oranından bulunur: 0,45 / (0,05 + 0,45) = 0,45 / 0,50 = %90.'),
  ('Bayesçi ardışık öğrenme sürecinde bugün elde edilen ilk kanıtla hesaplanan sonsal olasılık, yarın yeni ve bağımsız bir kanıt geldiğinde denklemde hangi rolü üstlenir?', 'Bir sonraki güncelleme adımının yeni önsel olasılığı haline gelir', ['İkinci kanıtın normalleştirme sabiti olarak paydaya yazılır', 'İlk kanıtın olabilirlik değeriyle toplanarak aritmetik ortalama oluşturur', 'Geçerliliğini yitirerek başlangıçtaki ilk tekdüze dağılıma sıfırlanır'], 'Bayesçi güncelleme zincirleme çalışır: dünün sonsal (posterior) olasılığı, bugünün yeni verisi karşısında önsel (prior) olasılık görevini görür.'),
  ('Harold Jeffreys\'in geliştirdiği Bayes çarpanı yorumlama ölçeğine göre, H1 hipotezinin H2\'ye göre Bayes çarpanı tam 1 değerine eşit çıktığında nasıl bir çıkarım yapılır?', 'Eldeki veri iki hipotezden hiçbirini diğerine karşı desteklememektedir', ['H1 hipotezi kesin olarak doğrulanmış ve sonsal olasılığı 1 olmuştur', 'Her iki hipotezin de yanlış olduğu kanıtlanmış ve üçüncü hipoteze geçilmiştir', 'H1 hipotezinin sonsal olasılığı H2 hipotezinin iki katına ulaşmıştır'], 'Bayes çarpanının 1 olması P(V|H1) = P(V|H2) demektir; veri iki hipotez arasında tamamen tarafsızdır ve önsel oranları değiştirmez.'),
  ('Makine öğrenmesinde e-posta sınıflandırırken kelimelerin birbirinden koşullu bağımsız olduğunu varsayarak Bayes kuralını çok hızlı uygulayan temel algoritmanın adı nedir?', 'Naif Bayes (Naive Bayes) sınıflandırıcısı', ['K-en yakın komşu kümeleyicisi', 'Temel bileşenler ayrıştırması', 'En küçük kareler budaması'], 'Özelliklerin sınıf etiketi verildiğinde birbirinden bağımsız olduğunu (\'naif\' varsayım) kabul ederek olabilirlikleri çarpan yöntem Naif Bayes\'tir.'),
  ('Aynı deney verisini inceleyen iki araştırmacıdan birinin sonsal olasılığı 0,72 iken diğerinin sonsal olasılığı 0,45 bulmasının Bayesçi çerçevedeki en doğal nedeni nedir?', 'Deney öncesinde hipoteze atadıkları önsel olasılık dağılımlarının birbirinden farklı olması', ['Toplam olasılıkların 1\'e eşit olması kuralının Bayes teoreminde geçerli olmaması', 'Koşullu olasılık tanımının örneklem ortalamasına göre rastgele yön değiştirmesi', 'Olabilirlik fonksiyonunun yalnızca negatif değerler alabilen bir seri oluşturması'], 'Olabilirlik (veri) aynı olsa bile başlangıçtaki önsel (prior) ağırlıklar farklıysa sonlu örneklemde farklı sonsal değerlere ulaşılır.'),
  ('Bir hipotezin önsel olasılığı P(H) = 0,20 iken yeni bir gözlem sonucunda sonsal olasılığı P(H|G) = 0,05 düzeyine düşmüştür. Bu durum gözlem G ile hipotez H arasındaki ilişki hakkında ne söyler?', 'Gözlem G, hipotez H yanlış olduğunda H doğru olduğuna kıyasla çok daha sık gerçekleşmektedir', ['Gözlem G ile hipotez H istatistiksel olarak birbirinden tamamen bağımsız iki olaydır', 'Hipotez H doğruyken gözlem G\'nin gerçekleşme olasılığı kesin olarak sıfıra eşittir', 'Gözlem G\'nin marjinal gerçekleşme olasılığı birden büyük bir değer almıştır'], 'Sonsal olasılığın önsale göre düşmesi P(G|H) < P(G|H\') olduğunu, yani kanıtın alternatif durumu desteklediğini gösterir.'),
  ('Bir öğrenci çoktan seçmeli 5 şıklı bir sorunun cevabını %60 olasılıkla gerçekten bilmekte, %40 olasılıkla ise şıklardan birini rastgele işaretlemektedir. Soruyu doğru yanıtladığı görülen bu öğrencinin cevabı rastgele atarak değil gerçekten bilerek yapmış olma olasılığı kaçtır?', '15/17', ['3/4', '5/6', '12/17'], 'Bilerek doğru = 0,60 × 1 = 0,60. Atarak doğru = 0,40 × (1/5) = 0,08. Sonsal olasılık = 0,60 / (0,60 + 0,08) = 60/68 = 15/17\'dir.'),
  ('Bir yarı iletken fabrikasında gece vardiyası üretimin %25\'ini, gündüz vardiyası %75\'ini gerçekleştiriyor. Gece vardiyasında üretilen çiplerin %4\'ü, gündüz vardiyasındakilerin %1\'i kusurlu çıkıyor. Kalite kontrolde kusurlu bulunan bir çipin gece vardiyasından çıkma olasılığı kaçtır?', '4/7', ['1/4', '3/7', '4/5'], 'Pay = 0,25 × 0,04 = 0,0100. Payda = 0,0100 + 0,75 × 0,01 = 0,0100 + 0,0075 = 0,0175. Oran = 100/175 = 4/7 olarak hesaplanır.'),
  ('Bir doğa fotoğrafçısı ormanda duyduğu uluma sesinin kurda ait olma önsel olasılığını 0,20, çakala ait olma olasılığını 0,80 olarak tahmin ediyor. Sesin 5 saniyeden uzun sürme olasılığı kurtlarda 0,70, çakallarda 0,10\'dur. Duyulan uluma 7 saniye sürdüğüne göre sesin kurttan gelme olasılığı kaçtır?', '7/11', ['5/11', '7/9', '3/5'], 'Pay = 0,20 × 0,70 = 0,14. Payda = 0,14 + 0,80 × 0,10 = 0,14 + 0,08 = 0,22. Sonsal olasılık = 14/22 = 7/11\'dir.'),
  ('Bayes ağlarında (Bayesian networks) oklarla birbirine bağlanan düğümler arasındaki yönlü kenarlar neyi temsil eder?', 'Rastgele değişkenler arasındaki doğrudan koşullu bağımlılık ve nedensel etki ilişkilerini', ['Değişkenlerin aritmetik ortalamalarının zaman içindeki azalış sıralamasını', 'Yalnızca birbirini dışlayan (ayrık) olayların kesişim kümelerini', 'Örneklem verilerinin bellekteki alfabetik depolanma adreslerini'], 'Yönlü çevrimsiz çizge (DAG) yapısındaki Bayes ağlarında her düğüm, ebeveyn düğümlerine koşullu olasılık tablosuyla bağlanır.'),
  ('Bir fabrikadaki A makinesi şişelerin %60\'ını, B makinesi %40\'ını kapatmaktadır. Kapak sızdırmazlık hatası A makinesinde binde 5, B makinesinde binde 15 oranındadır. Rastgele denetlenen bir şişede sızdırmazlık hatası bulunduğunda bunun A makinesinden çıkmış olma olasılığı kaçtır?', '1/3', ['1/2', '2/3', '3/5'], 'Pay = 0,60 × 0,005 = 0,003. Payda = 0,003 + 0,40 × 0,015 = 0,003 + 0,006 = 0,009. Oran = 0,003 / 0,009 = 1/3\'tür.'),
  ('Bilişsel bilimde insan beyninin duyusal belirsizlikleri geçmiş deneyimlerle (önsellerle) birleştirerek dış dünyayı algıladığını savunan kuramsal yaklaşıma ne ad verilir?', 'Bayesçi beyin (yordayıcı kodlama) hipotezi', ['Davranışçı koşullanma refleksi', 'Salt duyusal tabula rasa modeli', 'Doğrusal eşik aktivasyon kuramı'], 'Optik yanılsamaları ve duyusal tümleştirmeyi açıklayan Bayesçi beyin kuramı, beynin sürekli önsel beklentileri duyusal kanıtla güncellediğini öne sürer.'),
  ('Bir serada yetiştirilen domates fidelerinin %70\'i yerli tohum, %30\'u hibrit tohumdur. İlk ayda boyun 40 cm\'yi geçme olasılığı yerli fidelerde %20, hibrit fidelerde %70\'tir. Boyu ilk ayda 45 cm ölçülen bir fidenin hibrit tohumdan gelmiş olma olasılığı yüzde kaçtır?', '%60', ['%70', '%55', '%65'], 'Pay = 0,30 × 0,70 = 0,21. Payda = 0,70 × 0,20 + 0,21 = 0,14 + 0,21 = 0,35. Sonsal olasılık = 0,21 / 0,35 = 3/5 = %60 bulunur.'),
  ('Hava durumu spikeri sabah bülteninde yağmur önsel olasılığını %25 olarak açıklamıştır. Öğlen barometrede ani basınç düşüşü gözlemleniyor; bu düşüş yağmurlu günlerde %80, yağmursuz günlerde %10 olasılıkla görülür. Basınç düşüşünden sonra yağmurun güncellenmiş olasılığı kesir olarak kaçtır?', '8/11', ['4/7', '5/8', '3/4'], 'Pay = 0,25 × 0,80 = 0,20. Payda = 0,20 + 0,75 × 0,10 = 0,20 + 0,075 = 0,275. Sonsal olasılık = 200/275 = 8/11 olur.'),
  ('Bir arkeolojik kazıda çıkarılan kafatasının dişi bireye ait olma önsel olasılığı 0,50\'dir. Ölçülen kaş kemeri çıkıntısının düz olma olasılığı dişilerde 0,85, erkeklerde 0,15\'tir. Kaş kemeri düz ölçülen bu kafatasının dişi bireye ait olma olasılığı yüzde kaçtır?', '%85', ['%75', '%90', '%80'], 'Önsel olasılıklar eşit (0,50 - 0,50) ve olabilirliklerin toplamı 0,85 + 0,15 = 1,00 olduğundan sonsal olasılık doğrudan %85 çıkar.'),
  ('Bir kütüphanedeki tarih kitaplarının %40\'ı birinci katta, %60\'ı ikinci kattadır. Birinci kattaki tarih kitaplarının %30\'u ciltli, ikinci kattakilerin ise %50\'si ciltlidir. Ödünç bankosuna bırakılan ciltli bir tarih kitabının birinci kattan alınmış olma olasılığı kaçtır?', '2/7', ['3/7', '2/5', '4/9'], 'Pay = 0,40 × 0,30 = 0,12. Payda = 0,12 + 0,60 × 0,50 = 0,12 + 0,30 = 0,42. Sonsal olasılık = 12/42 = 2/7\'dir.'),
  ('Bir finans analisti merkez bankasının faiz artırma önsel olasılığını 0,40, sabit tutma olasılığını 0,60 olarak modelliyor. Enflasyon verisinin beklentiyi aşma olasılığı faiz artırılacak dönemlerde 0,75, sabit tutulacak dönemlerde 0,25\'tir. Enflasyon beklentiyi aştığında faiz artırma sonsal olasılığı kaç olur?', '2/3', ['3/5', '3/4', '4/7'], 'Pay = 0,40 × 0,75 = 0,30. Payda = 0,30 + 0,60 × 0,25 = 0,30 + 0,15 = 0,45. Sonsal olasılık = 0,30 / 0,45 = 2/3 bulunur.'),
  ('Gözlemlenen bir kanıt E\'nin hipotez H altında gerçekleşmesi kesinlikle imkânsızsa, yani P(E | H) = 0 ise ve P(E) > 0 koşulu sağlanıyorsa, E gözlemlendiğinde H\'nin sonsal olasılığı ne olur?', 'Önsel olasılığı ne kadar yüksek olursa olsun tam 0 değerine düşer', ['Önsel olasılığının tam yarısına gerileyerek sabitlenir', 'Normalleştirme sabitine bölünerek belirsiz (0/0) halini alır', 'Alternatif hipotezin önsel olasılığıyla yer değiştirir'], 'Karl Popper\'ın yanlışlanabilirlik ilkesinin Bayesçi karşılığıdır: P(E|H)=0 olduğunda pay 0 olur ve hipotez kesin olarak elenir.'),
  ('Bayes teoreminde tüm olası hipotezler kümesi {H1, H2, ..., Hk} oluşturulurken bu hipotezlerin hangi iki yapısal koşulu birlikte sağlaması gerekir?', 'İkişerli ayrık olmaları ve birleşimlerinin tüm örnek uzayı kaplaması', ['Hepsinin birbirine eşit önsel olasılığa sahip olması ve bağımsız olmaları', 'Kesişim olasılıklarının pozitif çıkması ve toplamlarının ikiden büyük olması', 'Yalnızca sürekli normal dağılımdan türetilmiş alt aralıklar olmaları'], 'Paydadaki tam olasılık açılımının geçerli olması için {H_i} ailesinin örnek uzayın bir parçalanışı (ayrık ve kapsayıcı) olması şarttır.'),
  ('Bir yapay zekâ ses tanıma sistemi kullanıcının söylediği kelimenin \'kasa\' veya \'masa\' olduğunu ayırt edecektir. Akustik sinyaller iki kelime için de bire bir aynı olabilirliği üretiyorsa (P(Ses|\'kasa\') = P(Ses|\'masa\')), Bayesçi dil modeli hangi kelimeyi seçer?', 'Cümle bağlamında önsel olasılığı daha yüksek olan kelimeyi', ['Alfabetik sırada daha önce gelen kelimeyi', 'Harf sayısı daha az olan kelimeyi', 'Her iki kelimeyi de silerek boş dizi döndüren seçeneği'], 'Akustik olabilirlikler eşitlendiğinde sonsal olasılığı belirleyen tek etken dil modelinden gelen bağlamsal önsel olasılıktır (örneğin \'banka ...\' bağlamında \'kasa\').'),
  ('İki kapalı zarftan birinde 100 TL, diğerinde 200 TL olduğunu değil; zarflardan A zarfında dört adet 50 TL ve bir adet 100 TL banknot, B zarfında iki adet 50 TL ve üç adet 100 TL banknot olduğunu düşünelim. Yazı-tura ile seçilen bir zarftan rastgele çekilen bir banknot 100 TL çıktığına göre bu zarfın B zarfı olma olasılığı kaçtır?', '3/4', ['3/5', '2/3', '4/5'], 'Önseller 1/2. 100 TL çekme olabilirliği A\'da 1/5, B\'de 3/5\'tir. Sonsal olasılık = (3/5) / (1/5 + 3/5) = 3/4 olarak hesaplanır.'),
  ('Klinik epidemiyolojide bir tanı testinin gerçekten hasta olan bireylerin yüzde kaçına doğru biçimde \'pozitif\' sonuç verebildiğini gösteren ölçüt hangisidir?', 'Duyarlılık (sensitivite)', ['Özgüllük (spesifisite) oranı', 'Pozitif öngörü değeri (PPV)', 'Negatif olabilirlik çarpanı'], 'Gerçek hastaları yakalama başarısını ölçen P(Test + | Hasta) koşullu olasılığı testin duyarlılığı (sensitivitesi) olarak tanımlanır.'),
  ('Sağlıklı (hastalığı taşımayan) bireylere uygulanan bir tarama testinin bu kişilere doğru biçimde \'negatif\' sonuç verme olasılığına ne ad verilir?', 'Özgüllük (spesifisite)', ['Duyarlılık (sensitivite) gücü', 'Negatif öngörü değeri (NPV)', 'Prevalans düzeltme katsayısı'], 'Sağlam bireyleri doğru ayırt etme yeteneğini ölçen P(Test - | Sağlam) koşullu olasılığı testin özgüllüğüdür.'),
  ('Gerçekte hastalığı taşımadığı halde tanı testinden hatalı olarak pozitif sonuç alan sağlıklı bir bireyin durumu hangi terimle karşılanır?', 'Yanlış pozitif', ['Yanlış negatif (false negative) vaka', 'Doğru negatif tarama sonucu', 'Gizli prevalans sapması'], 'Sağlıklı kişiye hatalı alarm verilmesi yanlış pozitifliktir ve olasılığı (1 - özgüllük) değerine eşittir.'),
  ('Hastalığı fiilen taşıyan bir hastanın uygulanan laboratuvar testinden hatalı biçimde \'temiz/negatif\' sonuç alması ne tür bir tanı hatasıdır?', 'Yanlış negatif', ['Yanlış pozitif (false positive) uyarısı', 'Doğru pozitif referans eşleşmesi', 'Özgüllük aşımı yanılsaması'], 'Hasta bireyin gözden kaçırılması yanlış negatifliktir; oranı (1 - duyarlılık) formülüyle hesaplanır.'),
  ('Test sonucu pozitif çıkan bir hastanın gerçekten o hastalığa sahip olma olasılığını ifade eden P(Hasta | Test +) değerine tıp istatistiğinde ne denir?', 'Pozitif öngörü değeri', ['Testin içsel duyarlılık katsayısı', 'Youden tanısal performans indeksi', 'Alıcı işletim karakteristiği alanı'], 'Hekimin ve hastanın pozitif sonuç sonrası en çok merak ettiği P(Hasta | +) sonsal olasılığı Pozitif Öngörü Değeri (PPV) adını alır.'),
  ('Tarama testinden negatif sonuç alan bir bireyin gerçekten sağlıklı olma olasılığını gösteren P(Sağlam | Test -) ölçütü aşağıdakilerden hangisidir?', 'Negatif öngörü değeri', ['Özgüllük (spesifisite) yüzdesi', 'Yanlış alarm dışlama katsayısı', 'Koşulsuz taban hastalık hızı'], 'Negatif sonucun kişiyi ne ölçüde rahatlattığını gösteren P(Sağlam | -) sonsal olasılığı Negatif Öngörü Değeridir.'),
  ('Havaalanındaki metal dedektörünün alarm hassasiyet eşiği çok sıkılaştırılıp en ufak metal parçada bile ötecek şekilde ayarlandığında sistem nasıl davranır?', 'Silah kaçırma riski (yanlış negatif) azalırken bozuk para yüzünden ötme (yanlış pozitif) artar', ['Bozuk para yüzünden ötme sıklığı azalırken tehlikeli cisimleri kaçırma olasılığı yükselir', 'Dedektörün özgüllüğü %100\'e yaklaşırken duyarlılığı %50\'nin altına geriler', 'Yolcu kuyruğundaki gereksiz üst aramaları tamamen ortadan kalkar'], 'Güvenlik sistemlerinde eşik düşürmek duyarlılığı maksimize eder ancak yanlış alarm (false alarm) maliyetini yükseltir.'),
  ('Kesin tanısı biyopsi ile konmuş 200 kanser hastasının 170\'inde pozitif, biyopsi ile sağlam olduğu doğrulanmış 400 kişinin ise 360\'ında negatif sonuç veren yeni bir kan testinin duyarlılığı ve özgüllüğü sırasıyla kaçtır?', 'Duyarlılık %85, özgüllük %90', ['Duyarlılık %90, özgüllük %85', 'Duyarlılık %85, özgüllük %80', 'Duyarlılık %68, özgüllük %95'], 'Duyarlılık = 170 / 200 = 0,85 (%85); Özgüllük = 360 / 400 = 0,90 (%90) olarak doğrudan tanım oranlarından bulunur.'),
  ('Duyarlılığı %80 ve özgüllüğü %95 olan bir tanı testinin pozitif olabilirlik oranı (LR+) kaçtır?', '16', ['4', '19', '8,42'], 'Yanlış pozitif oranı = 1 - 0,95 = 0,05\'tir. LR+ = Duyarlılık / (1 - Özgüllük) = 0,80 / 0,05 = 16 olarak hesaplanır.'),
  ('ROC eğrisinin altında kalan alan (AUC) tam 0,50 değerine eşit çıktığında sınıflandırıcı veya tanı testi hakkında ne söylenebilir?', 'Testin ayırt etme gücü yazı-tura atmaktan farksızdır; köşegen çizgi üzerindedir', ['Test hastaların tam yarısını %100 kesinlikle yakalayıp sıfır yanlış pozitif üretmektedir', 'Test mükemmel bir altın standarttır ve tüm eşiklerde hatasız çalışmaktadır', 'Veri kümesindeki hasta ve sağlıklı birey sayıları birbirine tam eşittir'], 'AUC = 0,50 değeri ROC grafiğindeki (0,0)-(1,1) şans köşegenine karşılık gelir ve testin hiçbir tanısal bilgi taşımadığını gösterir.'),
  ('Kan bankalarında bağışlanan kan üniteleri HIV ve Hepatit B açısından taranırken birinci öncelik olarak neden özgüllükten biraz ödün verilip duyarlılığı %99,9\'un üzerinde olan testler seçilir?', 'Enfekte bir kan ünitesini gözden kaçırmanın (yanlış negatif) alıcıda yol açacağı yıkım, sağlam üniteyi imha etmekten çok daha ağır olduğu için', ['Yüksek duyarlılıklı testlerin laboratuvar reaktif maliyetinin her zaman sıfıra yakın olması nedeniyle', 'Duyarlılık yükseldikçe yanlış pozitif sayısının da matematiksel olarak zorunlu biçimde sıfırlanması yüzünden', 'Kan bağışçılarının tamamında enfeksiyon prevalansının %50\'nin üzerinde seyretmesi sebebiyle'], 'Yanlış negatifin bedeli ölümcül bulaş iken yanlış pozitifin bedeli yalnızca bir ünite kanın ayrılıp doğrulama testine gönderilmesidir.'),
  ('Ağır yan etkileri olan kemoterapi veya radikal cerrahi gerektiren bir tanıyı kesinleştirmeden önce, ilk tarama testini izleyen ikinci aşamada neden çok yüksek özgüllüklü bir test tercih edilir?', 'Sağlıklı bir bireye yanlış pozitif tanı koyup onu ağır ve geri dönüşsüz bir tedaviye maruz bırakmamak için', ['Hastalık prevalansını genel nüfusta düşürüp hastane başvuru sayısını azaltmak amacıyla', 'İlk tarama testinin duyarlılığını geriye dönük olarak yeniden hesaplayabilmek için', 'Negatif öngörü değerini sıfıra indirerek tüm hastaları gözlem altında tutmak amacıyla'], 'Girişimsel veya toksik tedaviler öncesinde yanlış pozitifleri elemek hayati önem taşır; bunu da yüksek özgüllüklü doğrulama testi sağlar.'),
  ('Yeni geliştirilen hızlı bir tanı testinin gerçek duyarlılık ve özgüllüğünü ölçebilmek için tüm katılımcıların gerçek hastalık durumunu hatasız (veya eldeki en kesin yöntemle) belirleyen referans yönteme ne ad verilir?', 'Altın standart (gold standard) test', ['Plasebo kontrol ölçeği', 'Çift kör rastgeleleştirme kiti', 'vekil (surrogate) tarama şeridi'], 'Doku biyopsisi, PCR kültürü veya anjiyografi gibi gerçek durumu tanımlamakta referans kabul edilen yöntem altın standarttır.'),
  ('Bir klinikte incelenen 500 şüpheli vakada 2×2 tanı tablosu oluşturulmuştur: Doğru Pozitif (TP) = 90, Yanlış Pozitif (FP) = 30, Yanlış Negatif (FN) = 10 ve Doğru Negatif (TN) = 370\'tir. Bu tabloya göre testin Pozitif Öngörü Değeri (PPV) kaçtır?', '%75', ['%90', '%92,5', '%80'], 'PPV yalnızca test sonucu pozitif çıkanlar (TP + FP = 90 + 30 = 120) içindeki gerçek hastaların oranıdır: 90 / 120 = 3/4 = %75 (Duyarlılık olan %90 ile karıştırılmamalıdır!).'),
  ('ROC düzleminde (0, 1) koordinat noktası (yatay eksen = 0, dikey eksen = 1) neyi simgeler?', '%0 yanlış pozitif ve %100 duyarlılığa sahip kusursuz sınıflandırıcıyı', ['Herkese negatif sonuç veren tamamen duyarsız bir testi', 'Herkese pozitif sonuç veren sıfır özgüllüklü bir testi', 'Yanlış pozitif ile doğru pozitif oranının eşitlendiği rastgele noktayı'], 'Sol üst köşe olan (0, 1) noktasında 1 - Özgüllük = 0 (yani Özgüllük = 1) ve Duyarlılık = 1\'dir; sıfır hatalı ideal testi temsil eder.'),
  ('Bir veterinerlik fakültesinde geliştirilen brusella testi 300 enfekte sığırın 285\'ini pozitif, 500 sağlıklı sığırın ise 15\'ini pozitif bulmuştur. Bu testin yanlış negatif oranı ve yanlış pozitif oranı sırasıyla yüzde kaçtır?', 'Yanlış negatif %5, yanlış pozitif %3', ['Yanlış negatif %3, yanlış pozitif %5', 'Yanlış negatif %15, yanlış pozitif %15', 'Yanlış negatif %95, yanlış pozitif %97'], '300 enfekte sığırdan 15\'i kaçırılmıştır: FN oranı = 15/300 = %5. 500 sağlam sığırdan 15\'ine hatalı pozitif verilmiştir: FP oranı = 15/500 = %3.'),
  ('Bir yangın duman dedektörünün tost kızartırken çıkan hafif buharda bile alarm çalması, ancak gerçek bir yangın başladığında hiç sessiz kalmayıp mutlaka uyarması sensörün hangi özellik kombinasyonuna işaret eder?', 'Çok yüksek duyarlılık, görece düşük özgüllük', ['Çok yüksek özgüllük, oldukça düşük duyarlılık', 'Düşük duyarlılık ve düşük negatif öngörü değeri', 'Sıfır yanlış pozitif oranı ve yüksek yanlış negatif oranı'], 'Gerçek yangını hiç kaçırmaması duyarlılığının çok yüksek olduğunu, tost dumanında yanlış alarm vermesi ise özgüllüğünün düşük olduğunu gösterir.'),
  ('Bir deprem erken uyarı algoritması P-dalgası genliği eşiği aştığında trenleri otomatik durdurmaktadır. Mühendisler eşiği biraz yükselttiğinde sistemde aşağıdaki değişimlerden hangisi gözlemlenir?', 'Gereksiz tren durdurmalar (yanlış alarmlar) azalırken orta büyüklükteki bir depremi kaçırma riski artar', ['Hem gereksiz tren durdurmalar hem de depremi kaçırma olasılığı eşzamanlı olarak azalır', 'Sistemin özgüllüğü düşerken pozitif olabilirlik oranı sıfıra eşitlenir', 'Ağır kamyon geçişlerinden kaynaklanan hatalı durdurmalar iki katına çıkar'], 'Eşik yükseltildiğinde özgüllük artar (kamyon sarsıntısında yanlış alarm azalır), ancak duyarlılık düşer (sınırda kalan gerçek depremler kaçabilir).'),
  ('Klinik karar eşiği açısından bulaşıcı olmayan ve kendiliğinden iyileşen hafif bir mevsimsel nezlede hızlı testin yanlış negatif vermesi ile bakteriyel menenjitte testin yanlış negatif vermesi neden aynı kefeye konulamaz?', 'Kaçırılan menenjit vakasının ölüm/sekelle sonuçlanma kaybı çok yüksek olduğundan duyarlılık eşiği menenjitte çok daha sıkı tutulmalıdır', ['İstatistiksel olarak tüm bulaşıcı hastalıklarda yanlış pozitif ve yanlış negatif maliyetleri birbirine eşittir', 'Mevsimsel nezlede özgüllük her zaman sıfır olduğu için tanı testi tanımlanamaz', 'Bakteriyel menenjitte prevalans %90\'ın üzerinde olduğundan önsel olasılık hesaplanmaz'], 'Optimal tanı eşiği yalnızca testin ROC eğrisine değil, yanlış negatif (C_FN) ile yanlış pozitif (C_FP) kayıplarının oranına ve prevalansa bağlıdır.'),
  ('Bir tarım dronu elma bahçesindeki yaprak biti istilasını kızılötesi kamerayla tarıyor. İstilalı ağaçların %88\'ini doğru işaretleyen dron, sağlıklı ağaçların %89\'unu doğru biçimde temiz geçiyor. Dronun Youden J indeksi kaçtır?', '0,77', ['0,885', '0,78', '0,23'], 'Youden indeksi J = Duyarlılık + Özgüllük - 1 = 0,88 + 0,89 - 1 = 1,77 - 1 = 0,77 olarak bulunur.'),
  ('Bir otomotiv fabrikasında boya kalınlığı sensörü hatasız kaportaların %96\'sını onaylamakta, boya kusuru olan kaportaların ise %8\'ini hatalı biçimde onaylayıp bir sonraki istasyona geçirmektedir. Bu sensörün duyarlılığı (kusuru yakalama oranı) ve özgüllüğü kaçtır?', 'Duyarlılık %92, özgüllük %96', ['Duyarlılık %96, özgüllük %92', 'Duyarlılık %8, özgüllük %96', 'Duyarlılık %92, özgüllük %4'], 'Kusurlu kaportaların %8\'i kaçırılıyorsa (yanlış negatif = %8), kusuru yakalama duyarlılığı 100 - 8 = %92\'dir; sağlamları onaylama özgüllüğü ise %96\'dır.'),
  ('Bir siber saldırı tespit sistemi 250 alarm üretmiş, inceleme sonunda bunların 200\'ünün gerçek saldırı, 50\'sinin ise zararsız trafik olduğu anlaşılmıştır. Bu sistemin Yanlış Keşif Oranı (FDR) yüzde kaçtır?', '%20', ['%25', '%80', '%50'], 'FDR = FP / (TP + FP) = 50 / 250 = 0,20 (%20) olarak bulunur (PPV = %80 olduğundan 1 - 0,80 = %20).'),
  ('Bir e-posta güvenlik ağ geçidinde \'kimlik avı (phishing)\' puanı 0 ile 100 arasında üretiliyor. Sistem yöneticisi engelleme eşiğini 80 puandan 95 puana çıkardığında çalışanların gelen kutusunda ne gözlemlenir?', 'Meşru iş e-postalarının karantinaya düşmesi azalır, ancak bazı sinsi kimlik avı postaları gelen kutusuna sızmaya başlar', ['Gelen kutusuna sızan kimlik avı postaları tamamen biter, ancak meşru e-postaların yarısı silinir', 'Hem sızan kimlik avı postaları hem de engellenen meşru postalar aynı anda azalır', 'Sistemin pozitif öngörü değeri sıfırlanırken duyarlılığı %100 düzeyine çıkar'], 'Eşiği 95\'e yükseltmek yalnızca çok bariz saldırıları engeller: özgüllük artar (meşru postalar kurtulur), duyarlılık düşer (orta skorlu saldırılar sızar).'),
  ('Bir tarama çalışmasında 800 kişilik örneklemde hastalık prevalansı %25\'tir. Uygulanan testin duyarlılığı %80 ve özgüllüğü %85 olduğuna göre tabloda kaç adet \'Yanlış Pozitif\' ve kaç adet \'Yanlış Negatif\' birey yer alır?', '90 yanlış pozitif ve 40 yanlış negatif', ['40 yanlış pozitif ve 90 yanlış negatif', '120 yanlış pozitif ve 30 yanlış negatif', '60 yanlış pozitif ve 50 yanlış negatif'], '800 kişinin %25\'i = 200 hasta, 600 sağlam vardır. Hastaların %20\'si kaçırılır: FN = 200×0,20 = 40. Sağlamların %15\'i hatalı pozitif alır: FP = 600×0,15 = 90.'),
  ('Bir patoloji laboratuvarında yapay zekâ destekli hücre tarayıcısı \'ön eleme\' (triage) amacıyla kullanılıyor: Yapay zekânın \'kesinlikle normal\' dediği preparatlar arşive kaldırılıyor, \'şüpheli\' dedikleri ise uzman patolog tarafından inceleniyor. Bu iş akışının hasta güvenliğini tehlikeye atmaması için yapay zekânın hangi metriği %100\'e en yakın olmalıdır?', 'Negatif öngörü değeri (NPV) ve duyarlılığı', ['Pozitif öngörü değeri (PPV) ve yanlış negatif hızı', 'Yalnızca özgüllüğü', 'Pozitif olabilirlik oranının karesi'], 'Yapay zekânın \'normal\' deyip patoloğa hiç göstermediği preparatlarda tümör kaçmamalıdır; bunun için duyarlılık ve NPV ~%100 olmalıdır.'),
  ('Bir tanı kiti prospektüsünde \'Özgüllük: %99,5\' yazmaktadır. Bu bilginin doğrudan ve kesin anlamı aşağıdakilerden hangisidir?', 'Hastalığı taşımayan her 1000 sağlıklı kişiden ortalama 995\'ine negatif, 5\'ine yanlış pozitif sonuç verir', ['Test sonucu pozitif çıkan her 1000 kişiden 995\'i kesin olarak bu hastalığı taşımaktadır', 'Hastalığı taşıyan her 1000 hastadan 995\'ini kaçırmadan pozitif olarak saptar', 'Test sonucu negatif çıkan her 1000 kişiden yalnızca 5\'inde hastalık yoktur'], 'Özgüllük yalnızca sağlamlar kümesi üzerinden koşulludur: 1000 sağlamın 995\'i doğru negatif, 5\'i yanlış pozitif alır (PPV ile karıştırılmamalıdır!).'),
  ('İnsanların özel bir vaka hakkındaki betimleyici veya tanısal kanıta odaklanırken olayın toplumdaki genel görülme sıklığını hesaba katmaması bilişsel psikolojide hangi kavramla adlandırılır?', 'Temel oran yanılgısı', ['Geriye dönük kesinlik yanlılığı', 'Çıpalama ve uyumsuz ölçek etkisi', 'Doğrulayıcı örneklem daralması'], 'Önsel olasılığı (base rate / prevalans) göz ardı edip yalnızca yeni kanıtın gücüne göre hüküm verme hatası temel oran yanılgısıdır.'),
  ('Alman psikolog Gerd Gigerenzer\'in araştırmalarına göre hekimlerin ve öğrencilerin Bayes çıkarımındaki temel oran yanılgısını dramatik biçimde azaltan sunum yöntemi aşağıdakilerden hangisidir?', 'Koşullu yüzdeler yerine 1000 kişilik doğal frekans ağacı kullanmak', ['Olasılıkları ondalık kesir yerine doğal logaritma tabanında yazmak', 'Önsel olasılığı sorudan çıkarıp yalnızca olabilirlik oranını vermek', 'Duyarlılık ve özgüllük toplamını her zaman bire eşitleyerek sunmak'], '1000 kişiden 10\'u hasta, 9\'u pozitif; 990\'ı sağlam, 99\'u yanlış pozitif biçimindeki doğal frekanslar normalleştirme işlemini sezgisel hale getirir.'),
  ('Doğal frekans yöntemiyle düşünelim: 10.000 kişilik bir kasabada nadir bir sendrom tam 20 kişide bulunmaktadır. Tarama testi sendromlu 20 kişinin 18\'inde pozitif çıkarken, sendromsuz 9.980 kişinin 198\'inde yanlış pozitif sonuç üretmektedir. Testi pozitif çıkan bir kasabalının gerçekten sendromlu olma olasılığı kaçtır?', '1/12', ['9/10', '1/10', '9/109'], 'Toplam pozitif sayısı = 18 (doğru pozitif) + 198 (yanlış pozitif) = 216 kişidir. Bunların içindeki gerçek hasta oranı 18 / 216 = 1/12\'dir.'),
  ('Aranan durumun milyonda bir gibi aşırı nadir olduğu kitlesel güvenlik veya toplum taramalarında, testin özgüllüğü %99,9 kadar yüksek olsa bile Pozitif Öngörü Değerinin çok düşük çıkması olgusuna ne ad verilir?', 'Yanlış alarm seli', ['Aşırı uyum (overfitting) sönümlenmesi', 'Örneklem varyansı ve medyan çöküşü', 'Çift kör rastgele doğrulama sapması'], 'Aranan olay aşırı nadir olduğunda küçük yanlış pozitif oranı devasa masum kütlesiyle çarpılır ve gerçek alarmları boğan bir yanlış alarm seli üretir.'),
  ('Olasılıkları bilinen tüm olası sayısal sonuçların kendi gerçekleşme olasılıklarıyla çarpılıp toplanmasıyla elde edilen ağırlıklı ortalamaya istatistikte ne ad verilir?', 'Beklenen değer', ['Çeyrekler açıklığı', 'Tepe değer', 'Değişim katsayısı'], 'Kesikli bir X rastgele değişkeni için Σ x_i P(X = x_i) toplamı değişkenin beklenen değerini (matematiksel beklentisini) tanımlar.'),
  ('Bir rastgele değişkenin beklenen değeri (E[X]) hakkında aşağıdakilerden hangisi her zaman doğrudur?', 'Dağılımın olasılık kütlesinin ağırlık merkezini gösterir ve olası sonuçlardan birine eşit olmak zorunda değildir', ['Tek bir denemede en yüksek olasılıkla gerçekleşecek olan sonucu gösterir', 'Yalnızca simetrik dağılımlarda tanımlanabilir ve her zaman tam sayı çıkar', 'Olası en küçük değer ile en büyük değerin aritmetik ortalamasına her zaman eşittir'], 'Örneğin hilesiz bir zarın beklenen değeri 3,5\'tir; 3,5 zarda hiç gelmez ancak uzun dönemli ortalamanın denge (ağırlık) merkezidir.'),
  ('Bir yardım kermesinde 500 adet bilet tanesi 40 TL\'den satılmaktadır. Çekilişte 1 bilete 5.000 TL, 4 bilete 1.000\'er TL ve 10 bilete 300\'er TL ikramiye verilecektir. Tek bir bilet satın alan katılımcının bilet başına beklenen net kazancı (veya kaybı) kaç TL\'dir?', '-16 TL', ['+24 TL', '-20 TL', '-12 TL'], 'Dağıtılan toplam ikramiye = 5000 + 4×1000 + 10×300 = 12.000 TL\'dir. Bilet başı beklenen ikramiye = 12.000 / 500 = 24 TL; bilet bedeli 40 TL düşülünce net beklenti -16 TL\'dir.'),
  ('Hilesiz bir madeni para ve hilesiz altı yüzlü bir zar birlikte atılıyor. Para \'Tura\' gelirse zarın üst yüzündeki sayının 3 katı kadar TL kazanılıyor; para \'Yazı\' gelirse zarın üst yüzündeki sayı kadar TL kaybediliyor. Bu oyunun bir turdaki beklenen net kazancı kaç TL\'dir?', '3,5 TL', ['7,0 TL', '5,25 TL', '1,75 TL'], 'Zarın beklenen değeri 3,5\'tir. Tura (0,5) halinde beklenen kazanç 3×3,5 = 10,5 TL; Yazı (0,5) halinde beklenen kayıp -3,5 TL. Net beklenti = 0,5×10,5 + 0,5×(-3,5) = 3,5 TL.'),
  ('İki rakip arasında \'adil oyun\' (fair game) olarak nitelendirilen bir şans kurgusunun temel matematiksel koşulu nedir?', 'Her iki taraf için de net kazancın beklenen değerinin tam sıfıra eşit olması', ['Kazanma ve kaybetme olasılıklarının her koşulda %50 - %50 eşit olması', 'Olası sonuçların standart sapmasının sıfıra eşitlenerek riskin yok edilmesi', 'Oyunun tek bir turda kesin olarak berabere sonuçlanması'], 'Olasılıklar %50-%50 olmasa bile (örneğin %10 olasılıkla +90 TL, %90 olasılıkla -10 TL) beklenen net değişim E[Kazanç] = 0 ise oyun istatistiksel anlamda adildir.'),
  ('Aktüerya biliminde sigorta şirketinin işletme giderleri, vergiler ve kâr marjı eklenmeden önce yalnızca poliçeden doğacak beklenen hasar ödemesine eşit olan taban tutara ne ad verilir?', 'Saf prim (net risk primi)', ['Muafiyet eşiği (deductible)', 'Sürprim (yüklenmiş brüt tarife)', 'Koasürans kesinti tavanı'], 'Beklenen hasar E[Hasar] değerine tam karşılık gelen aktüeryal başabaş bedeli saf prim (pure/net risk premium) olarak adlandırılır.'),
  ('Değeri 800.000 TL olan bir yelkenli tekne için yıllık tam batma olasılığı %0,5 (800.000 TL hasar), orta ölçekli fırtına hasarı olasılığı %3 (60.000 TL hasar) ve hasarsız geçme olasılığı %96,5 olarak hesaplanmıştır. Bu teknenin yıllık aktüeryal saf primi kaç TL\'dir?', '5.800 TL', ['4.000 TL', '6.400 TL', '7.600 TL'], 'Saf prim = E[Hasar] = 0,005 × 800.000 + 0,03 × 60.000 + 0,965 × 0 = 4.000 + 1.800 = 5.800 TL olarak bulunur.'),
  ('Bir konut sigortası portföyünde poliçe başına yıllık beklenen yangın/su hasarı 1.400 TL, poliçe düzenleme ve acente komisyonu gideri ise 350 TL\'dir. Sigorta şirketi poliçeyi 2.100 TL brüt primle sattığında 10.000 poliçelik portföyden yıllık beklenen net işletme kârı kaç milyon TL olur?', '3,5 milyon TL', ['7,0 milyon TL', '4,2 milyon TL', '2,8 milyon TL'], 'Poliçe başına beklenen net kâr = 2.100 - (1.400 + 350) = 350 TL\'dir. Doğrusallık gereği 10.000 poliçede beklenen kâr = 10.000 × 350 = 3.500.000 TL (3,5 milyon TL) olur.'),
  ('Özel bir sağlık sigortası poliçesinde %20 \'koasürans\' (müşterek sigorta katılım payı) uygulanmakta, yani gerçekleşen her tedavi faturasının %80\'ini sigorta şirketi, %20\'sini hasta ödemektedir. Muafiyet bulunmayan bu poliçede sigortalının yıllık beklenen toplam tedavi faturası 15.000 TL ise şirketin üstlendiği beklenen ödeme kaç TL\'dir?', '12.000 TL', ['15.000 TL', '3.000 TL', '13.500 TL'], 'Beklenen değerin sabit çarpan özelliğinden E[0,80 × Fatura] = 0,80 × E[Fatura] = 0,80 × 15.000 = 12.000 TL bulunur.'),
  ('Sigorta şirketlerinin binlerce bağımsız konutu tek bir havuzda birleştirdiğinde poliçe başına ortalama gerçek hasarın beklenen değere (saf prime) çok yaklaşmasını sağlayan temel olasılık teoremi hangisidir?', 'Büyük Sayılar Yasası', ['Bayes Ters Olasılık Kuralı', 'Chebyshev Asimetri Eşitsizliği', 'Boole Birleşim Sınırı'], 'Bağımsız risklerin sayısı büyüdükçe örneklem ortalamasının varyansı 1/n hızıyla küçülür ve kişi başı gerçekleşen hasar E[X] saf primine yakınsar.'),
  ('Bir elektronik mağazası sattığı televizyonlar için 3 yıllık \'uzatılmış garanti\' paketi sunmaktadır. Bu 3 yıllık ek dönemde televizyonda panel arızası çıkma olasılığı %4 (onarım maliyeti 8.000 TL), anakart arızası çıkma olasılığı %6 (onarım maliyeti 2.500 TL) olarak belirlenmiştir. Mağaza uzatılmış garantiyi 900 TL\'ye sattığında paket başına beklenen brüt kârı kaç TL\'dir?', '430 TL', ['470 TL', '580 TL', '350 TL'], 'Beklenen toplam onarım maliyeti doğrusallıktan = 0,04×8.000 + 0,06×2.500 = 320 + 150 = 470 TL\'dir. Beklenen brüt kâr = 900 - 470 = 430 TL olur.'),
  ('Havayolu şirketlerinin ve otellerin, bazı müşterilerin son dakikada uçuşa/konaklamaya gelmeme (no-show) olasılığına karşı fiziki koltuk veya oda kapasitesinin biraz üzerinde bilet satması stratejisine ne ad verilir?', 'Fazla rezervasyon', ['Dinamik marjinal muafiyet', 'Tersine açık artırma tahsisi', 'Sıfır stoklu tam zamanında üretim'], 'Gelir yönetiminde boş koltuk kaybı (spoilage) ile fazla yolcuya ödenecek tazminat (denied boarding) maliyetini dengeleyen strateji fazla rezervasyondur.'),
  ('Yöneylem araştırmasında günlük gazete, taze simit veya mevsimlik moda ürünü gibi raf ömrü tek dönemlik olan ürünlerde belirsiz talep karşısında en uygun sipariş miktarını belirleyen klasik stok modelinin adı nedir?', 'Gazeteci çocuk (newsvendor) problemi', ['Gezgin satıcı rotalama problemi', 'Sırt çantası tamsayılı paketleme modeli', 'Markov kuyruk disiplini modeli'], 'Dönem sonunda satılamayan ürünün değer kaybettiği tek dönemli olasılıksal envanter modeli literatürde gazeteci çocuk (newsvendor) problemi olarak bilinir.'),
  ('Karar ağacı diyagramlarında karar vericinin kendi iradesiyle alternatif eylemlerden birini seçtiği kontrol noktaları hangi geometrik şekille gösterilir?', 'Kare düğüm', ['İçi boş daire (çember) düğüm', 'Eşkenar dörtgen (baklava) düğüm', 'Kesikli elips birleşim düğümü'], 'Standart karar ağacı gösteriminde kareler karar düğümlerini, daireler doğanın/belirsizliğin şans düğümlerini, üçgenler ise uç sonuç noktalarını simgeler.'),
  ('Bir karar ağacında karar vericinin denetimi dışındaki rastgele doğa durumlarının olasılıklarıyla dallandığı belirsizlik noktalarını hangi sembol temsil eder?', 'Daire (çember) düğüm', ['Kare biçimli seçim düğümü', 'Dikdörtgen alt süreç kutusu', 'Altıgen geri bildirim düğümü'], 'Piyasa talebi, hava durumu veya test sonucu gibi olasılıksal olayların dallandığı şans düğümleri karar ağaçlarında daire ile çizilir.'),
  ('Çok aşamalı bir karar ağacını çözerken en sağdaki uç sonuçlardan başlayıp sola (başlangıç köküne) doğru beklenen değerleri hesaplayarak optimal dalı belirleme yöntemine ne ad verilir?', 'Geriye doğru tümevarım', ['İleriye doğru açgözlü (greedy) budama', 'Derinlik öncelikli alfabetik tarama', 'Doğrusal gevşetme ve simpleks izdüşümü'], 'Dinamik programlama mantığına dayanan geriye katlama (rollback / backward induction) tekniğinde son aşamadan köke doğru şans düğümlerinde ortalama alınır, karar düğümlerinde en iyi dal seçilir.'),
  ('Geriye katlama yöntemiyle bir karar ağacı çözülürken \'şans düğümü\' ve \'karar düğümü\' üzerinde yapılan matematiksel işlemler sırasıyla hangisinde doğru verilmiştir?', 'Şans düğümünde olasılık ağırlıklı ortalama alınır; karar düğümünde en yüksek değerli dal seçilir', ['Şans düğümünde en yüksek olasılıklı dal seçilir; karar düğümünde tüm dalların aritmetik ortalaması alınır', 'Her iki düğüm türünde de yalnızca en kötü senaryoyu veren minimum değer geriye taşınır', 'Şans düğümünde dalların varyansı toplanır; karar düğümünde en düşük olasılıklı dal elenir'], 'Riske duyarsız karar verici şans düğümünde beklenen değeri hesaplar, kendi kontrolündeki karar düğümünde ise beklenen getiriyi maksimize eden (veya maliyeti minimize eden) dalı seçer.'),
  ('Bir yazılım girişimi \'Büyük Ölçekli Lansman\' yaparsa %40 olasılıkla 900.000 TL kazanacak, %60 olasılıkla 200.000 TL zarar edecektir; \'Butik Lansman\' yaparsa %70 olasılıkla 300.000 TL kazanacak, %30 olasılıkla 50.000 TL zarar edecektir. Beklenen parasal değer (EMV) ölçütüne göre optimal karar ve beklenen getirisi nedir?', 'Büyük ölçekli lansman; 240.000 TL', ['Butik lansman; 195.000 TL getiri', 'Büyük ölçekli lansman; 350.000 TL', 'Butik lansman; 225.000 TL getiri'], 'EMV(Büyük) = 0,40×900.000 + 0,60×(-200.000) = 360.000 - 120.000 = 240.000 TL. EMV(Butik) = 0,70×300.000 + 0,30×(-50.000) = 210.000 - 15.000 = 195.000 TL. 240.000 TL ile büyük lansman üstündür.'),
  ('Bir karar probleminde karar vericinin doğa durumunun hangisi olacağını önceden %100 kesinlikle öğrenebilecek bir kâhin veya hatasız bilgi kaynağı için ödemeye razı olacağı azami tutara ne ad verilir?', 'Kusursuz bilginin beklenen değeri', ['Örneklem bilgisinin marjinal varyansı', 'Batık araştırma maliyetinin iskonto değeri', 'Koşulsuz maksimum pişmanlık katsayısı'], 'EVPI = (Belirlilik altında beklenen getiri) - (Mevcut bilgiyle en yüksek EMV) farkıdır ve herhangi bir piyasa araştırması veya test için ödenebilecek üst sınırı belirler.'),
  ('Bir davacı mahkemeye gitmek yerine davalının sunduğu 300.000 TL kesin uzlaşma teklifini değerlendiriyor. Mahkemeye giderse avukatlık masrafı her durumda 60.000 TL tutacaktır; davayı %60 olasılıkla kazanıp 700.000 TL tazminat alacak, %40 olasılıkla kaybedip 0 TL alacaktır. Riske duyarsız davacı ne yapmalıdır?', 'Uzlaşmayı reddedip mahkemeye gitmelidir; beklenen net getiri 360.000 TL olur', ['300.000 TL kesin uzlaşma teklifini hemen kabul etmelidir; mahkeme beklentisi 280.000 TL\'dir', 'Mahkemeye gitmelidir; çünkü beklenen net getiri 420.000 TL düzeyindedir', 'İki seçeneğin beklenen değeri 300.000 TL\'de eşitlendiği için yazı-tura atmalıdır'], 'Mahkeme dalının beklenen brüt tazminatı 0,60×700.000 = 420.000 TL\'dir; kesin avukatlık masrafı 60.000 TL düşüldüğünde net EMV = 360.000 TL olup 300.000 TL uzlaşmadan yüksektir.'),
  ('Bir karar ağacında daha önce harcanmış ve hangi dal seçilirse seçilsin geri alınması mümkün olmayan geçmiş Ar-Ge harcamaları (batık maliyetler) optimal dal seçimini nasıl etkiler?', 'Tüm dallarda eşit biçimde geçmişte kaldığı için ileriye dönük optimal dal seçimini etkilemez', ['En çok batık maliyet harcanan dalın seçilme zorunluluğunu doğurur', 'Yalnızca şans düğümlerindeki olasılık ağırlıklarını iki katına çıkarır', 'Karar düğümündeki en kârlı dalın beklenen değerini sıfıra indirir'], 'Rasyonel karar analizinde yalnızca geleceğe yönelik artımsal (incremental) nakit akışları dikkate alınır; batık maliyet (sunk cost) sıralamayı değiştirmez.'),
  ('Karar analizinde girdi olasılıklarından veya gelir tahminlerinden birinin hangi değer aralığında değişmesi halinde optimal kararın değişmeyeceğini inceleyen tekniğe ne ad verilir?', 'Duyarlılık (hassasiyet) analizi', ['Kümeleme ve faktör ayrıştırması', 'Otokorelasyon serisi düzleştirmesi', 'Çift yönlü varyans homojenlik testi'], 'Parametrelerdeki belirsizliğin optimal stratejiyi hangi başabaş (break-even) eşiğinde değiştirdiğini sınayan yöntem duyarlılık (sensitivity) analizidir.'),
  ('Doğa durumlarının gerçekleşme olasılıklarının hiç bilinmediği \'tam belirsizlik altında karar verme\' ortamında, karar vericinin her alternatifin en yüksek getirisini bulup bunlar arasından en büyüğünü seçtiği aşırı iyimser ölçüte ne denir?', 'Maximax (iyimserlik) ölçütü', ['Maximin (Wald kötümserlik) ölçütü', 'Minimax pişmanlık (Savage) ölçütü', 'Laplace eş-olasılık ölçütü'], 'En iyilerin en iyisini hedefleyen Maximax kriteri, doğanın karar vericiye en elverişli durumu sunacağını varsayan tam iyimser yaklaşımdır.'),
  ('Tam belirsizlik altında Abraham Wald tarafından biçimselleştirilen ve her eylemin en kötü senaryodaki getirisini belirleyip bu en kötü sonuçlar içinden en yükseğini seçerek taban güvence sağlayan ölçüte ne ad verilir?', 'Maximin ölçütü', ['Maximax parlak senaryo ölçütü', 'Bayesçi maksimum olabilirlik ölçütü', 'Harmonik ortalama getiri ölçütü'], 'Kötülerin en iyisini (garanti edilen en yüksek alt sınırı) seçen Wald\'ın Maximin kuralı aşırı ihtiyatlı / kötümser karar yaklaşımını yansıtır.'),
  ('Bir sanayici üç yatırım projesinin (P1, P2, P3) üç ekonomik konjonktürdeki (Durgunluk, Normal, Canlanma) kâr tablosunu milyon TL cinsinden şöyle çıkarmıştır: P1 = (-20, +30, +90), P2 = (+10, +25, +45), P3 = (+15, +20, +25). Olasılıklar bilinmiyorken Maximin ve Maximax ölçütlerinin seçeceği projeler sırasıyla hangileridir?', 'Maximin: P3, Maximax: P1', ['Maximin: P2, Maximax: P1', 'Maximin: P1, Maximax: P3', 'Maximin: P3, Maximax: P2'], 'En kötü sonuçlar: min(P1)=-20, min(P2)=+10, min(P3)=+15 -> Maximin en yüksek taban olan P3\'ü (+15) seçer. En iyi sonuçlar: max(P1)=+90, max(P2)=+45, max(P3)=+25 -> Maximax P1\'i (+90) seçer.'),
  ('Tam belirsizlik altında Laplace (eş-olasılık) ölçütü, n adet doğa durumunun olasılıkları hakkında hiçbir bilgi olmadığında karar vericinin nasıl hareket etmesini önerir?', 'Her doğa durumuna 1/n eşit olasılık atayıp aritmetik ortalaması en yüksek alternatifi seçmesini', ['Ortadaki doğa durumuna 1 olasılık verip diğer tüm durumlara 0 olasılık atamasını', 'Yalnızca standart sapması en büyük olan uç alternatifi doğrudan tercih etmesini', 'Alternatiflerin geometrik ortalamasını alıp en küçük olan seçeneği işaretlemesini'], 'Yetersiz neden ilkesine dayanan Laplace ölçütü, tüm doğa durumlarını 1/n olasılıkla eş ağırlıklı sayarak satır ortalaması en büyük eylemi seçer.'),
  ('Bir karar tablosunda A eyleminin her doğa durumundaki getirisi B eyleminin aynı doğa durumundaki getirisinden büyük veya eşit, en az bir doğa durumunda ise kesin olarak büyükse A ve B arasındaki ilişkiye ne denir?', 'A eylemi B eylemine baskındır', ['A ve B eylemleri birbirinin eşlenik yedek stratejisidir', 'B eylemi Minimax pişmanlık açısından A eyleminden üstündür', 'A ve B eylemleri arasında sıfır toplamlı Nash dengesi kurulmuştur'], 'Baskınlık (dominance) ilkesi gereği hiçbir senaryoda daha iyi olmayan ve en az bir senaryoda kesin daha kötü olan domine edilmiş B seçeneği olasılıklardan bağımsız olarak karar ağacından budanır.'),
  ('Kesin olarak 50.000 TL almak ile \'%50 olasılıkla 100.000 TL, %50 olasılıkla 0 TL\' kazandıran bir çekilişe girmek arasında kesin 50.000 TL\'yi tercih eden bir bireyin risk tutumu ve servet fayda fonksiyonu u(W) nasıldır?', 'Riskten kaçınan; içbükey (konkav, u\'\'(W) < 0) fayda fonksiyonu', ['Risk seven; dışbükey (konveks, u\'\'(W) > 0) fayda fonksiyonu', 'Riske duyarsız; doğrusal (u\'\'(W) = 0) fayda fonksiyonu', 'Riskten kaçınan; üstel artan dışbükey fayda fonksiyonu'], 'Beklenen değeri aynı (50.000 TL) olan kesin parayı belirsiz çekilişe yeğlemek riskten kaçınmadır ve azalan marjinal faydayı yansıtan içbükey (u\'\' < 0) eğriyle modellenir.'),
  ('Karar kuramında bir bireyin elindeki riskli bir piyangodan vazgeçmek için kabul edeceği en düşük garanti nakit tutara (yani u(CE) = E[u(W)] eşitliğini sağlayan tutara) ne ad verilir?', 'Kesinlik eşdeğeri', ['Aktüeryal risk primi', 'Fırsat maliyeti tavanı', 'Marjinal ikame oranı'], 'Bireyi riskli oyun ile garanti para arasında kayıtsız bırakan kesin tutar CE (certainty equivalent - kesinlik eşdeğeri) olarak tanımlanır.'),
  ('Bir tıbbi müdahalenin halka \'%90 hayatta kalma oranı sağlıyor\' diye sunulduğunda büyük destek görmesi, bire bir aynı müdahalenin \'%10 ölümle sonuçlanıyor\' diye sunulduğunda ise reddedilmesi hangi bilişsel etkiyi örneklendirir?', 'Çerçeveleme etkisi (framing effect)', ['Temel oran ihmali (base-rate neglect)', 'Hayatta kalma yanlılığı (survivorship bias)', 'Örneklem büyüklüğüne duyarsızlık'], 'Matematiksel olarak özdeş iki olasılık dağılımının kazanç veya kayıp çerçevesinde sunulmasına göre kararın değişmesi Tversky ve Kahneman\'ın çerçeveleme etkisidir.'),
  ('Sağlık ekonomisinde farklı tıbbi müdahalelerin karar ağaçlarında sonuç birimi olarak yalnızca \'hayatta kalma yılı\' değil, yaşam kalitesi katsayısıyla (0 = ölüm, 1 = tam sağlıklı yaşam) ağırlıklandırılmış süre kullanılır. Bu standart ölçü biriminin adı nedir?', 'Kaliteye ayarlanmış yaşam yılı', ['Kümülatif hastane yatış devir hızı', 'Kaba ölüm hızı düzeltme çarpanı', 'Standartlaştırılmış morbidite varyansı'], 'Karar ağaçlarında yaşam süresi ile sağlık fayda ağırlığını çarpan QALY (Quality-Adjusted Life Year), maliyet-etkililik analizlerinin temel sonuç birimidir.'),
  ('Üç rakip ekonomik tahmin modelinin eldeki veriler ışığında sonsal model olasılıkları P(M1|V) = 0,50, P(M2|V) = 0,30 ve P(M3|V) = 0,20 olarak hesaplanmıştır. Modellerin gelecek çeyrek büyüme tahminleri sırasıyla %4,0, %2,0 ve %1,0 ise Bayesçi Model Ortalaması (BMA) tahmini yüzde kaçtır?', '%2,8', ['%4,0', '%2,33', '%3,1'], 'BMA tahmini sonsal model olasılıklarıyla ağırlıklandırılmış ortalamadır: 0,50×4,0 + 0,30×2,0 + 0,20×1,0 = 2,0 + 0,6 + 0,2 = %2,8 bulunur.'),
  ('Bir lojistik firması kış aylarında kamyonlarına kar zinciri takıp takmama kararını inceliyor: Zincir takmanın sabit işçilik/aşınma maliyeti 800 TL\'dir. Güzergâhta tipi çıkma olasılığı %20\'dir; tipi çıktığında zincirsiz kamyonun yolda kalma zararı 6.000 TL iken zincirli kamyonda ek zarar 0 TL\'dir. Beklenen maliyet açısından firma ne yapmalıdır?', 'Zincir takmalıdır; beklenen maliyet 1.200 TL\'den 800 TL\'ye inerek 400 TL tasarruf sağlar', ['Zincir takmamalıdır; çünkü %80 olasılıkla hava açık olacağından 800 TL boşa gider', 'Zincir takmalıdır; beklenen maliyet 6.000 TL\'den 800 TL\'ye inerek 5.200 TL tasarruf sağlar', 'İki seçeneğin beklenen maliyeti 1.000 TL\'de eşitlendiği için fark etmez'], 'Zincirsiz beklenen maliyet = 0,20×6.000 + 0,80×0 = 1.200 TL\'dir. Zincirli beklenen maliyet kesin 800 TL\'dir. 800 < 1.200 olduğundan zincir takmak beklenen maliyeti 400 TL düşürür.'),
  ('Narenciye bahçesi olan bir üretici gece don uyarısı aldığında bahçedeki ısıtıcı fanları çalıştırmanın gecelik yakıt maliyetini C = 15.000 TL, fanlar çalıştırılmaz ve don vurursa ürün kaybını L = 100.000 TL olarak hesaplamıştır. Meteorolojinin açıkladığı don olasılığı yüzde kaçın üzerindeyse fanları çalıştırmak rasyoneldir?', '%15\'in üzerindeyse', ['%13\'ün üzerindeyse', '%50\'nin üzerindeyse', '%85\'in üzerindeyse'], 'Maliyet/Kayıp eşiği C / L = 15.000 / 100.000 = 0,15 (%15) olur. Don olasılığı %15\'i aştığında beklenen ürün kaybı (p×100.000), 15.000 TL yakıt giderini geçer.'),
  ('Çoktan seçmeli 4 şıklı bir sınavda her doğru yanıt +1 net kazandırırken, rastgele işaretleme yapan bir öğrencinin beklenen net puanının tam 0 olması için kaç yanlış yanıt 1 doğru yanıtı götürmelidir?', '3 yanlış 1 doğruyu götürmelidir', ['4 yanlış 1 doğruyu götürmelidir', '2 yanlış 1 doğruyu götürmelidir', '5 yanlış 1 doğruyu götürmelidir'], '4 şıklı soruda rastgele doğru bulma olasılığı 1/4, yanlış yapma olasılığı 3/4\'tür. Beklenen net = (1/4)×(+1) + (3/4)×(-c) = 0 denkleminden c = 1/3 bulunur; yani 3 yanlış 1 doğruyu götürür.'),
  ('İkinci Dünya Savaşı\'nda üsse geri dönen bombardıman uçaklarındaki mermi deliklerinin kanat ve kuyrukta yoğunlaştığını, motor çevresinde ise neredeyse hiç delik olmadığını gören istatistikçi Abraham Wald neden kanatları değil motor bölümünü zırhlamayı önermiştir?', 'Motorundan vurulan uçaklar düşüp geri dönemediği için eldeki örneklem yalnız sağ kalanları yansıtmaktadır', ['Kanatlardaki metal alaşım mermileri mıknatıs gibi kendine çekerek motoru korumuştur', 'Motor bölümünün yüzey alanı kanatlardan on kat daha geniş olduğu için yoğunluk düşük görünmüştür', 'Uçaksavar nişancıları yalnızca kuyruk ve kanat bölgelerine ateş etmek üzere eğitilmiştir'], 'Hayatta kalma yanlılığının (survivorship bias) en ünlü örneğidir: Gözlemlenen delikler uçağın vurulup da hala uçabildiği bölgeleri gösterir; görünmeyen kayıp uçaklar ise motordan vurulanlardır.'),
  ('Mağazaya bir saat içinde gelen müşteri sayısı N\'nin beklenen değeri E[N] = 20\'dir. Gelen her müşterinin diğerlerinden ve N\'den bağımsız olarak yaptığı harcama X\'in beklenen değeri E[X] = 150 TL ise, Wald özdeşliğine göre mağazanın bir saatlik beklenen toplam cirosu kaç TL\'dir?', '3.000 TL', ['1.500 TL', '3.150 TL', '2.850 TL'], 'Rastgele sayıda bağımsız özdeş değişkenin toplamı S_N için Wald özdeşliği E[S_N] = E[N] × E[X] verir: 20 × 150 = 3.000 TL.'),
  ('Her bağımsız denemede başarı olasılığının sabit p = 0,20 olduğu bir kalite testinde, ilk başarılı sonuca ulaşana kadar yapılması gereken beklenen toplam deneme sayısı (başarılı deneme dahil) kaçtır?', '5 deneme', ['4 deneme', '20 deneme', '2,5 deneme'], 'Geometrik dağılımın beklenen değeri E[X] = 1 / p formülüyle bulunur: 1 / 0,20 = 5 deneme.'),
  ('Acil servise saatte ortalama λ = 12 hasta başvurmakta ve her hasta kayıt, muayene ve tetkik dahil serviste ortalama W = 2,5 saat geçirmektedir. Little yasasına göre herhangi bir anda acil serviste bulunan beklenen hasta sayısı kaçtır?', '30 hasta', ['14,5 hasta', '24 hasta', '15 hasta'], 'Little yasası L = λ × W uyarınca 12 hasta/saat × 2,5 saat = 30 hasta bulunur.'),
  ('Adli tıp babalık testlerinde şüpheli babanın genetik belirteçlerinin çocuğa geçme olasılığının rastgele bir erkeğinkine oranına \'Babalık İndeksi\' (PI = Bayes çarpanı) denir. Dava öncesi önsel olasılık 0,50 (1:1 bahis) alındığında ve genetik test Babalık İndeksini PI = 999 olarak bulduğunda babalık sonsal olasılığı yüzde kaçtır?', '%99,9', ['%99,0', '%95,0', '%99,5'], 'Önsel bahis 1:1 iken sonsal bahis 1 × 999 = 999:1 olur. Olasılığa çevrildiğinde 999 / (999 + 1) = 999/1000 = %99,9 elde edilir.'),
  ('Belirtisiz bir kişide tesadüfen saptanan sınırda bir laboratuvar sapmasının yeni görüntülemeleri, onların da şüpheli gölgeler çıkararak biyopsiyi ve biyopsi komplikasyonlarını tetiklediği zincirleme tıbbi sürece klinik karar analizinde ne ad verilir?', 'Tanısal şelale (kaskad) etkisi', ['Altın standart yakınsama etkisi', 'Terapötik eşlenik sönümlenme', 'Çift kör plasebo dengelenmesi'], 'Düşük önsel olasılıklı bireylerde yapılan gereksiz taramaların ürettiği yanlış pozitiflerin birbiri ardına daha girişimsel testleri tetiklemesi tanısal kaskad (cascade) etkisidir.'),
  ('Klinik araştırmalarda kontrol grubunda olay riski %12, ilaç grubunda ise %7 olarak bulunmuştur (Mutlak Risk Azalması ARR = %5). Tek bir olumsuz olayı önlemek için kaç hastanın tedavi edilmesi gerektiğini gösteren NNT (Number Needed to Treat) değeri kaçtır?', '20 hasta', ['5 hasta', '12 hasta', '14,3 hasta'], 'NNT = 1 / ARR = 1 / (0,12 - 0,07) = 1 / 0,05 = 20 hastadır; yani 20 hasta tedavi edildiğinde beklenen 1 olay önlenir.'),
  ('Kesikli bir rastgele değişkenin alabileceği her bir değerin kendi gerçekleşme olasılığı ile çarpılıp toplanmasıyla elde edilen uzun dönem ağırlıklı ortalamaya istatistikte ne ad verilir?', 'Beklenen değer', ['Standart sapma katsayısı', 'Medyan sapma ölçütü', 'Çeyrekler arası açıklık'], 'Beklenen değer, bir rastgele değişkenin olası değerlerinin olasılıklarıyla ağırlıklandırılmış toplamıdır.'),
  ('Bir kasko şirketi, yıllık kaza yapma olasılığı %2 olan bir araç grubu için kaza başına ortalama 50.000 TL hasar ödemesi öngörmektedir. Şirketin zarar etmemesi için keseceği poliçenin saf risk primi en az kaç TL olmalıdır?', '1.000 TL', ['1.250 TL tutarında', '2.000 TL tutarında', '2.500 TL seviyesinde'], 'Saf risk primi beklenen hasara eşittir: 0,02 × 50.000 = 1.000 TL.'),
  ('Karar ağaçlarında şans (doğa durumu) düğümlerini ve karar vericinin kendi kontrolündeki seçim düğümlerini göstermek için sırasıyla hangi geometrik şekiller kullanılır?', 'Daire ve kare', ['Üçgen ve dikdörtgen', 'Eşkenar dörtgen ve daire', 'Kare ve altıgen'], 'Karar ağaçlarında belirsizlik içeren şans düğümleri daire, karar vericinin seçim yaptığı düğümler ise kare ile simgelenir.'),
  ('Bir elektronik mağazası sattığı kulaklıklar için 240 TL\'ye ek garanti paketi sunmaktadır. Kulaklığın garanti süresince bozulma olasılığı %5 ve bozulduğunda mağazaya değişim maliyeti 3.000 TL olduğuna göre mağazanın paket başına beklenen net kazancı kaç TL\'dir?', '90 TL', ['110 TL net kazanç', '150 TL net kazanç', '60 TL birim getiri'], 'Beklenen maliyet 0,05 × 3.000 = 150 TL\'dir; 240 - 150 = 90 TL beklenen net kazançtır.'),
  ('Bir karar vericinin kesin olarak elde edeceği 500 TL\'yi, %50 olasılıkla 1.000 TL ve %50 olasılıkla 0 TL kazandıran bir çekilişe tercih etmesi beklenen fayda kuramında hangi kavramla açıklanır?', 'Riskten kaçınma', ['Riske duyarsızlık eğilimi', 'Risk severlik davranışı', 'Kusursuz bilgi arayışı'], 'Beklenen parasal değeri aynı (500 TL) olan iki seçenekten kesin olanı tercih etmek riskten kaçınma davranışıdır.'),
  ('Gelecekteki doğa durumunun hangisi olacağını kesin olarak bilen bir uzmana karar vericinin ödemeye razı olacağı en yüksek tutarı ifade eden kavram hangisidir?', 'Kusursuz bilginin beklenen değeri', ['Örneklem bilgisinin varyansı', 'Beklenen fırsat kaybı toplamı', 'Koşullu olasılık katsayısı'], 'Kusursuz bilginin beklenen değeri (EVPI), belirsizliği tamamen ortadan kaldıran bilgi için ödenebilecek üst sınırdır.'),
  ('Bir havayolu şirketi 180 koltuklu uçağına 182 bilet satmıştır. Yolcuların uçuşa gelmeme durumlarına göre 0 yolcunun açıkta kalma olasılığı 0,70; 1 yolcunun açıkta kalma olasılığı 0,20 ve 2 yolcunun açıkta kalma olasılığı 0,10\'dur. Açıkta kalan her yolcuya 4.000 TL tazminat ödendiğine göre uçuş başına beklenen tazminat maliyeti kaç TL\'dir?', '1.600 TL', ['1.200 TL toplam maliyet', '2.000 TL toplam maliyet', '2.400 TL beklenen gider'], 'Beklenen açıkta kalan yolcu sayısı: 0(0,70) + 1(0,20) + 2(0,10) = 0,40 kişi; 0,40 × 4.000 = 1.600 TL.'),
  ('Paranın marjinal faydasının sabit olduğu doğrusal bir fayda fonksiyonuna (örneğin U(x) = 3x + 10) sahip olan bir yatırımcının risk tutumu nasıldır?', 'Riske karşı kayıtsız', ['Aşırı derecede riskten kaçınan', 'Yüksek getiri için risk seven', 'Belirsizlikten tamamen uzak duran'], 'Doğrusal fayda fonksiyonunda beklenen faydayı maksimize etmek beklenen parasal değeri maksimize etmekle özdeştir; bu kişiler riske nötrdür.'),
  ('Bir simitçi sabahları tanesi 6 TL maliyetle simit alıp 15 TL\'ye satmakta, akşam satılmayan simitleri ise fırına tanesi 2 TL\'den iade etmektedir. Simitçinin talep fazlası verdiği bir günde satılmayan her bir simit için katlandığı birim fazla stok maliyeti kaç TL\'dir?', '4 TL', ['6 TL birim zarar', '9 TL kâr kaybı', '13 TL net maliyet'], 'Fazla stok maliyeti (Cu veya Co içinde Co): Maliyet - Hurda değeri = 6 - 2 = 4 TL\'dir.'),
  ('Karar ağacı analizinde en sağdaki uç (sonuç) düğümlerden başlayarak sola, yani başlangıç karar düğümüne doğru beklenen değerleri hesaplayıp optimal olmayan dalları eleme yöntemine ne denir?', 'Geriye doğru tümevarım', ['İleriye doğru olasılık yayılımı', 'Doğrusal programlama gevşetmesi', 'Monte Carlo benzetim tekniği'], 'Karar ağaçları sondan başa doğru çözülür; bu işleme geriye doğru tümevarım (backward induction / folding back) denir.'),
  ('Bir karar probleminde kusursuz bilginin beklenen değeri (EVPI) sıfır çıkmışsa bu durum aşağıdakilerden hangisini kesin olarak gösterir?', 'Mevcut en iyi kararın tüm doğa durumlarında zaten en yüksek getiriyi sağladığını', ['Doğa durumlarının gerçekleşme olasılıklarının birbirine tamamen eşit olduğunu', 'Karar vericinin tüm seçeneklerde kesin olarak parasal zarar ettiğini', 'Seçenek sayısının doğa durumu sayısından daha fazla olduğunu'], 'Bir alternatif her doğa durumunda baskın (en iyi) ise ek bilgi karar değiştirmez ve EVPI sıfır olur.'),
  ('Bir cep telefonu ekran koruma sigortası yıllık 350 TL\'ye satılmaktadır. Yıl içinde ekranın bir kez kırılma olasılığı 0,08 (onarım bedeli 2.500 TL), iki kez kırılma olasılığı 0,01 (toplam onarım bedeli 5.000 TL) ve hiç kırılmama olasılığı 0,91\'dir. Sigorta şirketinin poliçe başına beklenen onarım gideri kaç TL\'dir?', '250 TL', ['200 TL beklenen gider', '275 TL beklenen gider', '300 TL toplam ödeme'], 'Beklenen gider: 0,08 × 2.500 + 0,01 × 5.000 + 0,91 × 0 = 200 + 50 = 250 TL.'),
  ('Beklenen parasal değer ölçütüne göre optimal olan bir karar seçeneği aynı zamanda aşağıdaki ölçütlerden hangisini her zaman minimum yapar?', 'Beklenen fırsat kaybını', ['En kötü durum zararını', 'Getirilerin standart sapmasını', 'En düşük olasılıklı maliyeti'], 'Beklenen parasal değeri (EMV) maksimize eden alternatif, her zaman beklenen fırsat kaybını (EOL) minimize eden alternatiftir.'),
  ('Bir otel 95 odası için hafta sonu 96 rezervasyon kabul etmiştir. Tüm müşterilerin gelme olasılığı %35 olup bu durumda açıkta kalan 1 müşteriyi komşu otele yerleştirmenin maliyeti 3.200 TL\'dir. En az bir iptal olma olasılığı %65 olduğuna göre bu fazladan rezervasyonun beklenen yerleştirme maliyeti kaç TL\'dir?', '1.120 TL', ['1.280 TL beklenen maliyet', '2.080 TL beklenen maliyet', '960 TL ek harcama'], 'Açıkta kalma yalnızca tüm müşteriler geldiğinde (%35) oluşur: 0,35 × 3.200 = 1.120 TL.'),
  ('Daniel Bernoulli\'nin 1738 yılında ortaya attığı, beklenen değeri sonsuz olan bir yazı-tura oyununa insanların neden çok sınırlı bir giriş ücreti ödemek istediğini açıklayan ünlü problem hangisidir?', 'St. Petersburg paradoksu', ['Monty Hall kapı ikilemi', 'Ellsberg belirsizlik paradoksu', 'Mahkûmların ikilemi modeli'], 'St. Petersburg paradoksu, sonsuz beklenen parasal değere rağmen sonlu beklenen fayda kavramının doğuşuna yol açmıştır.'),
  ('Stok yönetiminde tek dönemlik (gazeteci çocuk) modelinin temel uygulanma koşulu aşağıdakilerden hangisidir?', 'Ürünün dönem sonunda değerini büyük ölçüde yitirmesi ve sonraki döneme devredilememesi', ['Talebin yılın her gününde sabit ve kesin olarak önceden biliniyor olması', 'Tedarik süresinin sıfır olması ve gün içinde sınırsız kez ek sipariş verilebilmesi', 'Birim satış fiyatının birim alış maliyetinden her zaman daha düşük belirlenmesi'], 'Gazeteci çocuk (newsvendor) modeli; gazete, taze gıda, moda ürünü gibi tek satış dönemli ve bozulabilir/değer kaybeden ürünler içindir.'),
  ('Bir çiftçi tarlasına buğday ekerse yağışlı havada 120.000 TL, kurak havada 40.000 TL kazanacaktır. Hava durumunun yağışlı olma olasılığı 0,60 ve kurak olma olasılığı 0,40 ise buğday ekmenin beklenen parasal değeri kaç TL\'dir?', '88.000 TL', ['80.000 TL ortalama kazanç', '92.000 TL ortalama kazanç', '76.000 TL beklenen gelir'], '0,60 × 120.000 + 0,40 × 40.000 = 72.000 + 16.000 = 88.000 TL.'),
  ('İçbükey (konkav) bir fayda fonksiyonuna sahip birey için servet düzeyi arttıkça eklenen her 1.000 TL\'nin sağladığı ek fayda nasıl değişir?', 'Pozitiftir ancak giderek azalır', ['Sabit bir oranda hızla artar', 'Sıfıra eşit kalmaya devam eder', 'Negatif değer alarak toplamı düşürür'], 'İçbükey fayda fonksiyonu (U\'>0, U\'\'<0) azalan marjinal faydayı temsil eder; servet arttıkça ek fayda pozitif kalır ama azalır.'),
  ('Bir çekilişte 1.000 adet bilet satılmakta, tek bir bilete 18.000 TL büyük ikramiye ve 10 bilete de 700 TL teselli ikramiyesi verilmektedir. Bir biletin fiyatı 40 TL olduğuna göre tek bir bilet alan kişinin beklenen net kazancı kaç TL\'dir?', '-15 TL', ['-22 TL beklenen kayıp', '-10 TL beklenen kayıp', '+25 TL beklenen kazanç'], 'Bilet başına beklenen ikramiye: (18.000 × 1 + 700 × 10) / 1.000 = 25.000 / 1.000 = 25 TL. Net kazanç: 25 - 40 = -15 TL.'),
  ('Bir şans oyununun beklenen parasal değerine eşit olup, karar vericinin bu şans oyunu ile arasında kayıtsız kaldığı garanti para miktarına ne ad verilir?', 'Kesinlik eşdeğeri', ['Risk primi katsayısı', 'Beklenen pişmanlık tutarı', 'İçsel getiri oranı'], 'Karar vericinin belirsiz bir kura ile aynı beklenen faydayı sağlayan garanti para miktarına kesinlik eşdeğeri (certainty equivalent) denir; soruda genel tanımı sorulmuş ancak şans oyununun beklenen değerine eşit olma zorunluluğu yalnız riske nötrde vardır, düzeltelim: karar vericinin şans oyunuyla aynı faydayı gördüğü garanti tutar kesinlik eşdeğeridir.'),
  ('Bir beyaz eşya üreticisi çamaşır makinelerine 3 yıllık ücretsiz garanti vermektedir. Bir makinenin 3 yıl içinde arıza yapmama olasılığı 0,85, küçük arıza yapma olasılığı 0,12 (maliyet 1.000 TL) ve büyük arıza yapma olasılığı 0,03 (maliyet 6.000 TL) ise satış fiyatına eklenmesi gereken ortalama garanti maliyeti kaç TL\'dir?', '300 TL', ['240 TL garanti payı', '360 TL garanti payı', '180 TL ortalama gider'], 'Beklenen garanti maliyeti: 0,85(0) + 0,12(1.000) + 0,03(6.000) = 120 + 180 = 300 TL.'),
  ('Bir karar ağacında A seçeneği %30 olasılıkla 200 birim, %70 olasılıkla 100 birim kazandırırken; B seçeneği kesin olarak 125 birim kazandırmaktadır. Beklenen parasal değer ölçütüne göre hangi seçenek ve kaç birim farkla tercih edilmelidir?', 'A seçeneği, 5 birim farkla', ['B seçeneği, 5 birim farkla', 'A seçeneği, 15 birim farkla', 'B seçeneği, 25 birim farkla'], 'E(A) = 0,30(200) + 0,70(100) = 60 + 70 = 130 birim. E(B) = 125 birim. A seçeneği 130 - 125 = 5 birim farkla üstündür.'),
  ('Bir yatırımcının bir piyango biletine biçtiği kesinlik eşdeğeri 420 TL iken piyango biletinin beklenen parasal değeri 500 TL olarak hesaplanmıştır. Aradaki 80 TL\'lik fark literatürde nasıl adlandırılır?', 'Risk primi', ['Kusursuz bilgi bedeli', 'Net bugünkü değer', 'Fırsat maliyeti farkı'], 'Beklenen parasal değer ile kesinlik eşdeğeri arasındaki fark (EMV - CE = 500 - 420 = 80 TL) risk primidir.'),
  ('Bir etkinlik organizatörü açık hava konseri düzenlerse güneşli havada 90.000 TL kâr edecek, yağmurlu havada 30.000 TL zarar edecektir. Kapalı salon kiralarsa hava ne olursa olsun 42.000 TL kâr edecektir. Yağmur olasılığı %25 olduğuna göre beklenen kârı en yüksek seçenek kaç TL getirir?', '60.000 TL', ['67.500 TL beklenen kâr', '42.000 TL garanti kâr', '52.500 TL beklenen kâr'], 'Açık hava beklenen kârı: 0,75 × 90.000 + 0,25 × (-30.000) = 67.500 - 7.500 = 60.000 TL. Kapalı salon 42.000 TL olduğundan en yüksek beklenen kâr 60.000 TL\'dir.'),
  ('Bir otopark işletmecisi 50 araçlık kapalı otoparkı için aylık abonman satmaktadır. Abonelerin her iş günü otoparka gelmeme durumu nedeniyle 54 abonman satıldığında otoparkın tam dolup taşma yapmama olasılığı 0,80; 1 abonenin dışarıda kalma olasılığı 0,15 ve 2 abonenin dışarıda kalma olasılığı 0,05\'tir. Dışarıda kalan her abonenin günlük vale ve komşu otopark ücreti olan 200 TL\'yi işletmeci karşıladığına göre iş günü başına beklenen taşma maliyeti kaç TL\'dir?', '50 TL', ['40 TL günlük maliyet', '65 TL günlük maliyet', '80 TL beklenen gider'], 'Beklenen dışarıda kalan abone sayısı = 0(0,80) + 1(0,15) + 2(0,05) = 0,25 kişi. Günlük beklenen maliyet = 0,25 × 200 = 50 TL.'),
  ('Tek dönemlik stok (gazeteci çocuk) probleminde optimal sipariş miktarını belirleyen Cu / (Cu + Co) kesrine literatürde ne ad verilir?', 'Kritik oran', ['Varyasyon katsayısı', 'Güvenlik stoku çarpanı', 'Ekonomik sipariş oranı'], 'Cu / (Cu + Co) oranına kritik oran (critical fractile / critical ratio) adı verilir.'),
  ('Bir kasko poliçesinde "2.500 TL muafiyet" bulunması hem sigorta şirketinin prim fiyatını düşürmekte hem de sigortalının aracını daha dikkatli kullanmasını sağlamaktadır. Muafiyet uygulamasının sürücü davranışını dikkatli olmaya yöneltmesi hangi sorunu azaltmaya yöneliktir?', 'Ahlaki tehlikeyi', ['Ters seçimi', 'Örneklem yanlılığını', 'Sistematik piyasa riskini'], 'Sigortalandıktan sonra bireyin dikkatsiz davranarak hasar olasılığını artırması ahlaki tehlikedir (moral hazard); muafiyet, zararın ilk kısmını sigortalıya yükleyerek bu sorunu azaltır.'),
  ('Bir kırtasiyeci okul açılış haftasında tanesi 80 TL\'den özel ajanda alıp 140 TL\'ye satmaktadır. Hafta sonunda satılmayan ajandalar toptancıya 60 TL\'den iade edilebilmektedir. Kırtasiyeci 50 ajanda aldığında talebin 40 adet olma olasılığı 0,30 ve en az 50 adet olma olasılığı 0,70 ise kırtasiyecinin beklenen net kârı kaç TL\'dir?', '2.760 TL', ['3.000 TL beklenen kâr', '2.580 TL beklenen kâr', '2.840 TL haftalık kazanç'], 'Talep 40 ise (0,30): 40 adet satılır (40 × 60 = 2.400 TL kâr), 10 adet iade edilir (10 × (-20) = -200 TL zarar) => Net 2.200 TL. Talep ≥ 50 ise (0,70): 50 adedin tamamı satılır => Net 50 × 60 = 3.000 TL. Beklenen net kâr = 0,30(2.200) + 0,70(3.000) = 660 + 2.100 = 2.760 TL!'),
  ('Bir karar ağacında başlangıçtaki karar düğümünden "Yeni Fabrika Kur" ve "Fason Üretim Yaptır" olmak üzere iki dal çıkmaktadır. Geriye doğru katlama işlemi sonunda "Yeni Fabrika Kur" dalının beklenen değeri 420 bin TL, "Fason Üretim Yaptır" dalının beklenen değeri ise 475 bin TL bulunmuştur. Başlangıç karar düğümünün üstüne yazılacak beklenen değer kaç bin TL\'dir?', '475 bin TL', ['447,5 bin TL ortalama', '895 bin TL toplam değer', '420 bin TL alt sınır'], 'Karar düğümünde (kare) rasyonel karar verici beklenen değeri maksimize eden dalı seçer: max(420, 475) = 475 bin TL.'),
  ('Bir sinema salonu sattığı mısır menülerinin içine %4 olasılıkla "Ücretsiz Sinema Bileti" (salon maliyeti 125 TL) ve %10 olasılıkla "Küçük İçecek Kuponu" (salon maliyeti 30 TL) yerleştirmektedir; kalan menülerde hediye kuponu yoktur. Bu kampanyanın satılan her bir mısır menüsüne getirdiği beklenen hediye maliyeti kaç TL\'dir?', '8 TL', ['11 TL menü maliyeti', '6,5 TL menü maliyeti', '15,5 TL beklenen gider'], 'Beklenen hediye maliyeti = 0,04 × 125 + 0,10 × 30 = 5 + 3 = 8 TL.'),
  ('Kesinlikle artan ve içbükey (konkav) bir fayda fonksiyonuna sahip birey için servet düzeyi arttıkça eklenen her 1.000 TL\'nin sağladığı marjinal fayda nasıl değişir?', 'Pozitiftir ancak giderek azalır', ['Sabit bir oranda hızla artar', 'Sıfıra eşit kalmaya devam eder', 'Negatif değer alarak toplamı düşürür'], 'Artan içbükey fayda fonksiyonu azalan marjinal faydayı temsil eder; servet arttıkça ek fayda pozitif kalır ama azalır.'),
  ('Karar vericinin belirsiz bir şans oyunu ile arasında kayıtsız kaldığı (aynı beklenen faydayı gördüğü) garanti para tutarına ne ad verilir?', 'Kesinlik eşdeğeri', ['Risk primi katsayısı', 'Beklenen pişmanlık tutarı', 'İçsel getiri oranı'], 'Belirsiz bir kura ile aynı beklenen faydayı sağlayan kesin para miktarına kesinlik eşdeğeri (certainty equivalent) denir.'),
  ('Bir otopark işletmecisi 50 araçlık kapalı otoparkı için aylık abonman satmaktadır. 54 abonman satıldığında iş günlerinde taşma olmama olasılığı 0,80; 1 abonenin dışarıda kalma olasılığı 0,15 ve 2 abonenin dışarıda kalma olasılığı 0,05\'tir. Dışarıda kalan her abonenin komşu otopark ücreti olan 200 TL\'yi işletmeci ödediğine göre iş günü başına beklenen taşma maliyeti kaç TL\'dir?', '50 TL', ['40 TL günlük maliyet', '65 TL günlük maliyet', '80 TL beklenen gider'], 'Beklenen dışarıda kalan abone sayısı = 1(0,15) + 2(0,05) = 0,25 kişi; 0,25 × 200 = 50 TL.'),
  ('Bir kasko poliçesinde hasarın ilk 2.500 TL\'sinin sigortalı tarafından karşılanmasını öngören muafiyet maddesi konulması, sürücünün aracını daha özenli kullanmasını sağlayarak hangi sorunu azaltır?', 'Ahlaki tehlikeyi', ['Ters seçimi', 'Örneklem yanlılığını', 'Sistematik piyasa riskini'], 'Sigorta sonrasında bireyin dikkatsiz davranarak hasar olasılığını artırması ahlaki tehlikedir; muafiyet bu davranışı dizginler.'),
  ('Bir sinema salonu sattığı mısır menülerinin içine %4 olasılıkla "Ücretsiz Bilet" (salon maliyeti 125 TL) ve %10 olasılıkla "İçecek Kuponu" (salon maliyeti 30 TL) koymaktadır; kalan menülerde kupon yoktur. Satılan her mısır menüsünün beklenen hediye maliyeti kaç TL\'dir?', '8 TL', ['11 TL menü maliyeti', '6,5 TL menü maliyeti', '15,5 TL beklenen gider'], 'Beklenen hediye maliyeti = 0,04 × 125 + 0,10 × 30 = 5 + 3 = 8 TL.'),
];
